import unittest
from ci.run import suite
def ids(items):
    for item in items:
        if isinstance(item, unittest.TestSuite):
            yield from ids(item)
        else:
            yield item.id()
names = set(ids(suite()))
assert any(x.endswith('.LedgerTest.test_refund') for x in names), names
assert any(x.endswith('.CoreTest.test_base') for x in names), names
