files.plan.py:
import json
from pathlib import Path
def build(connector):
    pin = json.loads(Path('requirements.json').read_text())[connector]['adapter']
    available = json.loads(Path('wheel-index.json').read_text())['adapter']
    if pin not in available:
        raise ValueError(pin)
    return {'adapter': pin}

